/**
 * Fetches inference results from a local Python machine learning service.
 * Implements defensive error handling and timeout protection.
 */
async function fetchInferencePredictions(payload, timeoutMs = 5000) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch("http://127.0.0.1:8000/predict", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
      signal: controller.signal
    });

    if (!response.ok) {
      throw new Error(`HTTP Error: ${response.status} ${response.statusText}`);
    }

    const data = await response.json();
    return data;
  } catch (error) {
    if (error.name === "AbortError") {
      console.error(`Request timed out after ${timeoutMs}ms`);
    } else {
      console.error("Network or inference pipeline failure:", error.message);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId); // Prevent timer leak
  }
}

